import type {
  TransactionListItemForCanvasser,
  TransactionListItemForManager,
  TransactionListItemForAdmin,
} from '~/client';

export function isTransactionListItemForCanvasser(
  item: TransactionListItemForCanvasser | TransactionListItemForManager | TransactionListItemForAdmin
): item is TransactionListItemForCanvasser {
  return !isTransactionListItemForAdminManager(item);
}

export function isTransactionListItemForAdminManager(
  item: TransactionListItemForCanvasser | TransactionListItemForManager | TransactionListItemForAdmin
): item is TransactionListItemForManager | TransactionListItemForAdmin {
  return 'reason_code' in item;
}

export function isTransactionListForCanvasser(
  list: Array<TransactionListItemForCanvasser | TransactionListItemForManager | TransactionListItemForAdmin>
): list is Array<TransactionListItemForCanvasser> {
  return Boolean(list.every(isTransactionListItemForCanvasser));
}

export function isTransactionListForAdminManager(
  list: Array<TransactionListItemForCanvasser | TransactionListItemForManager | TransactionListItemForAdmin>
): list is Array<TransactionListItemForManager | TransactionListItemForAdmin> {
  return Boolean(list.every(isTransactionListItemForAdminManager));
}
