<template>
  <section class="grid grid-cols-2 gap-6">
    <PageTitle title="Transactions" class="col-span-2" show-doc>
      <NuxtLink :to="navigationButtonData.to">
        <Button>{{ navigationButtonData.label }}</Button>
      </NuxtLink>
    </PageTitle>
    <EarningsBranchInfoCard
      v-if="earnings && earnings.status !== 'not_registered' && isCanvasser"
      :status="earnings.status"
      :onboarding-link="earnings.onboarding_link"
      :transactions-button="false"
      :loading="isEarningsLoading"
      :error="earningsError?.data.details"
    />
    <TransactionsListFilters :params="params" class="col-span-2" />
    <Card class="col-span-2">
      <CardHeader v-if="isCanvasser">
        <CardTitle>History</CardTitle>
      </CardHeader>
      <CardContent class="!p-0 !md:p-0">
        <AppLoader v-if="isTransactionsListLoading" variant="inline" subject="transactions list" />
        <AppError
          v-else-if="transactionsListError"
          :error="transactionsListError"
          title="Failed to load transactions list"
          variant="table"
          :action="transactionsRefetch"
          action-text="Retry"
        />
        <AppGuidedEmpty v-else-if="showGuided && guidedContent" v-bind="guidedContent" variant="table" />
        <AppEmpty
          v-else-if="!transactions || transactions.items.length === 0"
          subject="transactions list"
          variant="table"
        />
        <template v-else>
          <TransactionsCanvasserList v-if="isCanvasser" :list="canvasserList">
            <template #footer>
              <ResponsiveTableFooter v-if="transactions.total_count > 0" :colspan="3" :cols="4" :cols-sm="4">
                <AppPagination
                  :page="params.page"
                  :size="params.size"
                  :total="transactions.total_count"
                  label="transactions"
                />
              </ResponsiveTableFooter>
            </template>
          </TransactionsCanvasserList>
          <TransactionsAdminManagerList v-else-if="isAdminOrManager" :list="adminManagerList">
            <template #footer>
              <ResponsiveTableFooter v-if="transactions.total_count > 0" :colspan="4" :cols="4" :cols-sm="4">
                <AppPagination
                  :page="params.page"
                  :size="params.size"
                  :total="transactions.total_count"
                  label="transactions"
                />
              </ResponsiveTableFooter>
            </template>
          </TransactionsAdminManagerList>
        </template>
      </CardContent>
    </Card>
  </section>
</template>

<script setup lang="ts">
import { useEarnings } from '~/queries/earnings/details';
import { transactionsGuidedEmpty } from '~/constants/guidedEmpty/earnings';
import type { TypedNuxtLink } from '#build/typed-router/typed-router';
import {
  getTransactionList,
  type GetTransactionListData,
  type GetTransactionListResponse,
  type SortType,
  type TransactionSortBy,
  type TransactionStatus,
  type TransactionListItemForCanvasser,
  type TransactionListItemForManager,
  type TransactionListItemForAdmin,
} from '~/client';
//TODO: Refactor transactions lists to be more unified

useHead({
  title: 'Transactions',
});

definePageMeta({
  roles: ['admin', 'manager', 'canvasser'],
  backLabel: 'transactions',
});

const { isCanvasser, isAdminOrManager } = useUserRole();

const route = useRoute();

const { earnings, isLoading: isEarningsLoading, error: earningsError } = useEarnings();

const params = computed<GetTransactionListData['query']>(() => {
  const urlParams = {
    ...parsePagination(route.query),
    sort_by: (route.query.sort_by as TransactionSortBy) || 'timestamp_created',
    sort_type: (route.query.sort_type as SortType) || 'desc',
    search_query: (route.query.search_query as string) || undefined,
    statuses: processArrayQueryParameterFromUrl<TransactionStatus>(route.query.statuses),
    canvasser_ids: processArrayQueryParameterFromUrl(route.query.canvasser_ids),
    created_date_from: (route.query.created_date_from as string) || undefined,
    created_date_to: (route.query.created_date_to as string) || undefined,
    amount_min: route.query.amount_min ? Number(route.query.amount_min) : undefined,
    amount_max: route.query.amount_max ? Number(route.query.amount_max) : undefined,
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
  };

  return Object.fromEntries(
    Object.entries(urlParams).filter(([_, value]) => value !== undefined)
  ) as unknown as GetTransactionListData['query'];
});

const {
  data: transactions,
  error: transactionsListError,
  isLoading: isTransactionsListLoading,
  refetch: transactionsRefetch,
} = useQuery({
  key: () => ['transactions-list', params.value],
  query: (): Promise<GetTransactionListResponse> => getTransactionList({ composable: '$fetch', query: params }),
});

const canvasserList = computed((): TransactionListItemForCanvasser[] => {
  const items = transactions.value?.items ?? [];
  return isTransactionListForCanvasser(items) ? items : [];
});

const adminManagerList = computed((): (TransactionListItemForAdmin | TransactionListItemForManager)[] => {
  const items = transactions.value?.items ?? [];
  return isTransactionListForAdminManager(items) ? items : [];
});

const navigationButtonData = computed<{ to: TypedNuxtLink['to']; label: string }>(() => {
  if (isCanvasser.value) {
    return { to: { name: 'earnings-balance' }, label: 'My Balance' };
  } else {
    return { to: { name: 'earnings' }, label: 'Earnings' };
  }
});

const isEmpty = computed(() => !transactions.value || transactions.value.items.length === 0);

const { guidedContent, showGuided } = useGuidedEmpty(transactionsGuidedEmpty, isEmpty);
</script>

<style scoped lang="scss"></style>
